nextflow_process {

    name "Test Process GLIMPSE2_LIGATE"
    script "../main.nf"

    process "GLIMPSE2_LIGATE"

    tag "modules_nfcore"
    tag "modules"
    tag "glimpse2"
    tag "glimpse2/ligate"
    tag "bcftools/index"
    tag "glimpse2/phase"

    test("Should run glimpse ligate") {
        setup {
            run("GLIMPSE2_PHASE") {
                script "../../phase/main.nf"
                process {
                """
                input_vcf = channel.of([
                    [ id:'input' ],
                    file(params.modules_testdata_base_path + "genomics/homo_sapiens/illumina/vcf/NA12878.chr21_22.1X.glimpse2.vcf.gz", checkIfExists: true),
                    file(params.modules_testdata_base_path + "genomics/homo_sapiens/illumina/vcf/NA12878.chr21_22.1X.glimpse2.vcf.gz.csi", checkIfExists: true),
                    [], []
                ]).combine(channel.of(
                    ["chr22:16570065-16597215", "chr22:16570065-16592216"],
                    ["chr22:16587172-16609999", "chr22:16592229-16609999"]
                ))

                ref_panel = channel.of([
                    file(params.modules_testdata_base_path + "genomics/homo_sapiens/popgen/1000GP.chr22.vcf.gz", checkIfExists:true),
                    file(params.modules_testdata_base_path + "genomics/homo_sapiens/popgen/1000GP.chr22.vcf.gz.csi", checkIfExists:true),
                ])

                map_file = channel.of([[]])

                // [meta, vcf, index, sample_infos, regionin, regionout,ref, index, map] [meta, fasta, fai]
                input[0] = input_vcf
                    .map { meta, vcf, index, list, sample, regionI, regionO ->
                        [[id: meta.id, region : regionI], vcf, index, list, sample, regionI, regionO]
                    }
                    .combine(ref_panel)
                    .combine(map_file)
                input[1] = channel.of([[],[],[]]).collect()
                input[2] = []
                """
                }
            }
            run("BCFTOOLS_INDEX") {
                script "../../../bcftools/index/main.nf"
                process {
                """
                input[0] = GLIMPSE2_PHASE.out.phased_variants
                """
                }
            }
        }

        when {
            process {
                """
                input[0] = GLIMPSE2_PHASE.out.phased_variants
                    .join(BCFTOOLS_INDEX.out.index)
                    .map{ meta, vcf, index -> [meta.subMap("id"), vcf, index]}
                    .groupTuple()
                """
            }
        }

        then {
            assert process.success
            assert snapshot(
                process.out.merged_variants.collect { meta, vcf -> [
                        meta,
                        file(vcf).name,
                        path(vcf).vcf.summary,
                        path(vcf).vcf.variantsMD5
                ] },
                process.out.findAll { key, val -> key.startsWith('versions') }
            ).match()
        }
    }

    test("Should run glimpse ligate -- stub") {
        options "-stub"
        when {
            process {
                """
                input[0] = [
                    [ id:'input' ],
                    file(params.modules_testdata_base_path + "genomics/homo_sapiens/illumina/vcf/NA12878.chr21_22.1X.glimpse2.vcf.gz", checkIfExists: true),
                    file(params.modules_testdata_base_path + "genomics/homo_sapiens/illumina/vcf/NA12878.chr21_22.1X.glimpse2.vcf.gz.csi", checkIfExists: true),
                ]
                """
            }
        }

        then {
            assert process.success
            assert snapshot(sanitizeOutput(process.out)).match()
        }
    }
}

